import { readFile, writeFile } from 'node:fs/promises';

const moduleName = 'endpoints/completePairing';
const sources = {};
for (const name of [moduleName, 'lib/pairing']) {
  sources[name] = await readFile(new URL('../serverless/tgcloud/' + name + '.js', import.meta.url), 'utf8');
}
await writeFile(new URL('./tgcloud-runtime.mjs', import.meta.url),
  '// Generated by node gateway/build-tgcloud-runtime.mjs from the Telegram runtime sources.\n' +
  'export const pairingModule = ' + JSON.stringify(moduleName) + ';\n' +
  'export const pairingSources = ' + JSON.stringify(sources, null, 2) + ';\n' + `

export async function completePairing(appToken, owner, code, installation) {
  const appId = /^(app[0-9]+):[A-Za-z0-9_-]+$/.exec(appToken || '')?.[1];
  if (!appId) throw new Error('Telegram Serverless не настроен');
  if (!Number.isSafeInteger(owner) || owner <= 0 ||
      typeof code !== 'string' || !/^[A-F0-9]{16}$/.test(code) ||
      typeof installation !== 'string' || !/^[a-f0-9]{64}$/.test(installation)) {
    throw new Error('Неверный запрос подключения');
  }
  const response = await fetch('https://cloud.telegram.org/' + appId + '/manage/run', {
    method: 'POST', redirect: 'manual',
    headers: { Authorization: 'Bearer ' + appToken, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      module: pairingModule,
      sources: pairingSources,
      args: { code, installation },
      ctx: { initData: { user: { id: owner } } },
    }),
  });
  let envelope;
  try { envelope = await response.json(); }
  catch { throw new Error('Telegram Serverless вернул неверный ответ'); }
  if (!response.ok || envelope?.ok !== true) throw new Error('Telegram Serverless отклонил подключение');
  const result = envelope.result?.result;
  if (typeof result?.generation !== 'string' || !/^[a-f0-9]{32}$/.test(result.generation) ||
      !Number.isSafeInteger(result.revision) || result.revision <= 0) {
    throw new Error('Telegram Serverless не подтвердил привязку');
  }
  return { generation: result.generation, revision: result.revision };
}
`);
